class Solution {
public:
    int findSubstringInWraproundString(string s) {
        int maxLen[26] = {0};
        int curLen = 0;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (i > 0 && (s[i] - s[i - 1] + 26) % 26 == 1) {
                curLen++;
            } else {
                curLen = 1;
            }
            int idx = s[i] - 'a';
            if (curLen > maxLen[idx]) {
                maxLen[idx] = curLen;
            }
        }
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            ans += maxLen[i];
        }
        return ans;
    }
};
